const fs = require('node:fs');
const vm = require('node:vm');
const assert = require('node:assert/strict');
const html = fs.readFileSync('index.html', 'utf8');
const script = html.match(/<script>([\\s\\S]*?)<\\/script>/)[1];
new vm.Script(script);
function setup(stored = null, blocked = false) {
 let focus, saved = stored;
 class Element {
  constructor(id) { this.id=id; this.value=''; this.hidden=true; this.disabled=false; this.attrs={}; this.events={}; this.textContent=''; }
  setAttribute(k,v) { this.attrs[k]=v; }
  getAttribute(k) { return this.attrs[k]; }
  addEventListener(k,fn) { this.events[k]=fn; }
  fire(k) { this.events[k]?.({preventDefault(){}}); }
  focus() { focus=this.id; }
  get validity() { const n=Number(this.value); return {valid: this.disabled || (this.value"'!=='"'' && n>=1 && Number.isInteger(n))}; }
 }
 const ids = [...html.matchAll(/id=\"(["'^"]+)"/g)].map(m=>m[1]);
 const nodes = Object.fromEntries(ids.map(id=>[id,new Element(id)]));
 nodes['"'guest-count'].value='1'; nodes['rsvp-section'].hidden=false;
 const yes=new Element('yes'), no=new Element('no'); yes.value='yes';no.value='no';
 const radios=[yes,no];
 const choose = value => { radios.forEach(r=>r.checked=r.value===value); radios.find(r=>r.checked).fire('change'); };
 const form=nodes['rsvp-form'];
 form.querySelectorAll=()=>radios;
 form.querySelector=s=>s.includes(':checked')?radios.find(r=>r.checked):s.includes('aria-invalid')?[nodes['guest-name'],...radios,nodes['guest-count']].find(e=>e.attrs['aria-invalid']==='true'):radios.find(r=>s.includes('\"'+r.value+'\"'));
 const doc={getElementById:id=>nodes[id],querySelector:s=>nodes[s.slice(1)]};
 const storage={getItem(){if(blocked)throw Error('Blocked');return saved},setItem(k,v){if(blocked)throw Error('Blocked');saved=v}};
 vm.runInNewContext(script,{document:doc,localStorage:storage});
 return {nodes,choose,submit:()=>form.fire('submit'),get saved(){return saved},get focus(){return focus}};
}
let f=setup(), n=f.nodes;
f.submit(); assert.equal(f.focus,'guest-name'); assert.equal(n['attendance-error'].hidden,false);
n['guest-name'].value='  '; f.choose('yes'); f.submit(); assert.equal(n['name-error'].hidden,false);
n['guest-name'].value='Alex Taylor'; n['guest-count'].value='1.5'; f.submit(); assert.equal(n['guests-error'].hidden,false);
n['guest-count'].value='0';f.submit();assert.equal(n['guests-error'].hidden,false);
n['guest-count'].value='2';n.dietary.value='One vegetarian';f.submit();assert.equal(n.confirmation.hidden,false);assert.match(n['response-summary'].textContent,/2 guests/);
const saved=f.saved;f=setup(saved);n=f.nodes;assert.equal(n.confirmation.hidden,false);n['edit-response'].fire('click');assert.equal(n['guest-name'].value,'Alex Taylor');assert.equal(n.dietary.value,'One vegetarian');
f.choose('no');assert.equal(n['attending-details'].hidden,true);f.submit();assert.equal(JSON.parse(f.saved).guests,0);assert.equal(n['response-summary'].textContent,'Regretfully declined');
f=setup(null,true);f.nodes['guest-name'].value='Alex Taylor';f.choose('yes');f.submit();assert.equal(f.nodes['save-error'].hidden,false);assert.equal(f.nodes.confirmation.hidden,true);
f=setup('{broken');assert.equal(f.nodes['rsvp-section'].hidden,false);
console.log('Passed: required fields, whitespace names, invalid counts, acceptance, decline, edit, persistence, blocked storage, corrupt storage.');
