from html.parser import HTMLParser
from pathlib import Path
class Check(HTMLParser):
    def __init__(self):
        super().__init__(); self.ids=[]; self.refs=[]
    def handle_starttag(self, tag, attrs):
        a=dict(attrs)
        if 'id' in a: self.ids.append(a['id'])
        for attr in ['for','aria-describedby','aria-labelledby']:
            self.refs.extend(a.get(attr,'').split())
c=Check();c.feed(Path('index.html').read_text())
assert len(c.ids)==len(set(c.ids)), 'Duplicate IDs'
assert set(c.refs)<=set(c.ids), 'Missing label or ARIA reference'
print('Passed: unique IDs and label/ARIA references. Single file, no external dependencies.')
